import React from "react";

const CustomTable = ({ cols, rows, visibleCols = {} }) => {
  const getVisible = (key) => visibleCols[key] ?? true;

  // Total number of visible columns for proper corner rounding
  const visibleColKeys = cols.filter((col) => getVisible(col.key));

  return (
    <div className="overflow-x-auto border rounded-xl max-h-[500px]">
      <table className="min-w-full text-left border border-gray-200 rounded-xl overflow-hidden">
        <thead className="sticky top-0 z-10 bg-[#E1D5C9] text-[#292929] text-sm">
          <tr>
            {visibleColKeys.map((col, i) => (
              <th
                key={i}
                className={`px-4 py-3 whitespace-nowrap ${
                  i === 0 ? "rounded-tl-xl" : ""
                } ${
                  i === visibleColKeys.length - 1 ? "rounded-tr-xl" : ""
                }`}
              >
                {col.label}
              </th>
            ))}
            <th className="px-4 py-3 whitespace-nowrap">
              Actions
            </th>
          </tr>
        </thead>

        <tbody>
          {rows.map((row, rIndex) => (
            <tr
              key={rIndex}
              className={`${
                rIndex % 2 === 0 ? "bg-white" : "bg-[#F5EFEB]"
              } text-[#292929] text-sm`}
            >
              {visibleColKeys.map((col, cIndex) => (
                <td
                  key={cIndex}
                  className={`px-4 py-3 whitespace-nowrap ${
                    rIndex === rows.length - 1 && cIndex === 0
                      ? "rounded-bl-xl"
                      : ""
                  } ${
                    rIndex === rows.length - 1 &&
                    cIndex === visibleColKeys.length - 1
                      ? "rounded-br-xl"
                      : ""
                  }`}
                >
                  {col.render ? col.render(row[col.key], row) : row[col.key]}
                </td>
              ))}

              <td className="px-4 py-3 whitespace-nowrap">
                <div className="flex gap-3">
                  {row.actions || <span className="text-gray-400">—</span>}
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default CustomTable;
